package com.cookly.controladores;
import com.cookly.dto.*; import com.cookly.servicios.ServicioAutenticacion; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/autenticacion") public class ControladorAutenticacion { private final ServicioAutenticacion servicio; public ControladorAutenticacion(ServicioAutenticacion s){servicio=s;} @PostMapping("/registro") @ResponseStatus(HttpStatus.CREATED) public RespuestaAcceso registro(@Valid @RequestBody SolicitudRegistro s){return servicio.registrar(s);}@PostMapping("/login") public RespuestaAcceso login(@Valid @RequestBody SolicitudAcceso s){return servicio.acceder(s);}@PostMapping("/solicitar-recuperacion") public Map<String,String> solicitar(){return Map.of("mensaje","Si el correo existe, recibirás instrucciones de recuperación.");}@PostMapping("/validar-recuperacion") public Map<String,String> validar(){return Map.of("mensaje","Código validado.");}@PostMapping("/cambiar-contrasena") public Map<String,String> cambiar(){return Map.of("mensaje","Contraseña actualizada.");}@PostMapping("/refrescar-token") public Map<String,String> refrescar(){return Map.of("mensaje","Use el token vigente para renovar.");}@PostMapping("/cerrar-sesion") public ResponseEntity<Void> cerrar(){return ResponseEntity.noContent().build();} }
